import hashlib,json,math,os,re
from pathlib import Path


def canonical(value):return json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()
def digest(value):return hashlib.sha256(canonical(value)).hexdigest()


def validate(manifest):
    if not isinstance(manifest,dict)or set(manifest)!={'batch_id','events','queries'}:raise ValueError('manifest schema')
    if not isinstance(manifest['batch_id'],str)or not re.fullmatch(r'[a-z0-9_-]{1,32}',manifest['batch_id']):raise ValueError('batch identity')
    if not isinstance(manifest['events'],list)or len(manifest['events'])>64 or not isinstance(manifest['queries'],list)or len(manifest['queries'])>8 or not(manifest['events']or manifest['queries']):raise ValueError('batch budget')
    for kind,fields in [('events',{'event_id','member','lon','lat','stamp'}),('queries',{'query_id','lon','lat','radius_m','now','max_age','limit'})]:
        seen=set();identity='event_id'if kind=='events'else'query_id'
        for row in manifest[kind]:
            if not isinstance(row,dict)or set(row)!=fields:raise ValueError('entry schema')
            if not isinstance(row[identity],str)or not 1<=len(row[identity].encode())<=128 or row[identity]in seen:raise ValueError('entry identity')
            seen.add(row[identity])
            for key,low,high in [('lon',-180,180),('lat',-85.05112878,85.05112878)]:
                if type(row[key])not in(int,float)or not low<=row[key]<=high or(type(row[key])is float and not math.isfinite(row[key])):raise ValueError('coordinate')
            if kind=='events':
                if not isinstance(row['member'],str)or not 1<=len(row['member'].encode())<=128 or type(row['stamp'])is not int or not 0<=row['stamp']<=2**53-1:raise ValueError('event version')
            else:
                if type(row['radius_m'])not in(int,float)or not 0<row['radius_m']<=10000 or(type(row['radius_m'])is float and not math.isfinite(row['radius_m'])):raise ValueError('radius')
                for key,low,high in [('now',0,2**53-1),('max_age',0,86400),('limit',1,100)]:
                    if type(row[key])is not int or not low<=row[key]<=high:raise ValueError('query bound')
    return digest(manifest)


def keys(prefix):
    if not isinstance(prefix,str)or not re.fullmatch(r'of:[a-f0-9]{16,48}:',prefix):raise ValueError('dedicated prefix')
    return[prefix+name for name in('geo','times','meta','batches','events','batch_events','queries')]


