def record(raw):
    if not isinstance(raw,str):raise ValueError('native receipt missing')
    value=json.loads(raw)
    if not isinstance(value,dict):raise ValueError('native receipt object required')
    for field in('candidates','items'):
        if field in value and not isinstance(value[field],list):raise ValueError('native JSON array required')
    return value


def native_preflight(command,prefix,manifest):
    managed=keys(prefix)
    for index,key in enumerate(managed):
        if command('TYPE',key)not in('none','zset'if index==0 else'hash'):raise ValueError('managed key type')
    flat_times=command('HGETALL',managed[1]);all_times=dict(zip(flat_times[::2],flat_times[1::2]))
    for raw in all_times.values():
        if not isinstance(raw,str)or not re.fullmatch(r'0|[1-9][0-9]*',raw)or int(raw)>2**53-1:raise ValueError('invalid existing timestamp')
    old=command('HGET',managed[3],manifest['batch_id'])
    epoch=command('HGET',managed[2],'epoch')
    if epoch is not None and(not re.fullmatch(r'0|[1-9][0-9]*',epoch)or int(epoch)>1000000000):raise ValueError('epoch budget')
    if old is not None:
        if record(old)['digest']!=digest(manifest):raise ValueError('batch digest conflict')
    else:
        pending=command('HGET',managed[2],'open')
        if pending not in(None,''):raise ValueError('another batch pending')
    new_members=set();versions={};additional=0
    for event in manifest['events']:
        known=command('HGET',managed[4],event['event_id'])
        if known is not None and record(known)['input_sha256']!=digest(event):raise ValueError('event identity conflict')
        raw=command('HGET',managed[1],event['member'])
        if raw is not None and(not re.fullmatch(r'0|[1-9][0-9]*',raw)or int(raw)>2**53-1):raise ValueError('invalid existing timestamp')
        if event['member']not in versions:versions[event['member']]=None if raw is None else int(raw)
        if known is None and(versions[event['member']]is None or versions[event['member']]<event['stamp']):
            additional+=1;versions[event['member']]=event['stamp']
        if command('ZSCORE',managed[0],event['member'])is None:new_members.add(event['member'])
    if command('ZCARD',managed[0])+len(new_members)>10000:raise ValueError('candidate budget exceeded')
    if int(epoch or 0)+additional>1000000000:raise ValueError('epoch budget')
    return managed


ARTIFACTS=('input.json','events.jsonl','queries.jsonl','manifest.json','audit.json')+tuple(name+'-%03d.json'%i for name in('candidates','result')for i in range(8))


def directory_for(root,batch_id):
    root=Path(root).resolve();root.mkdir(parents=True,exist_ok=True);directory=root/batch_id
    if directory.is_symlink():raise ValueError('generation symlink')
    directory.mkdir(exist_ok=True)
    if directory.resolve()!=directory or any((directory/name).is_symlink()for name in ARTIFACTS):raise ValueError('artifact escape')
    return directory


def publish(path,value):
    data=canonical(value)+b'\n'
    if path.is_symlink():raise ValueError('artifact symlink')
    temporary=path.with_name(path.name+'.tmp-'+str(os.getpid()))
    try:
        with temporary.open('xb')as stream:stream.write(data);stream.flush();os.fsync(stream.fileno())
        try:os.link(temporary,path,follow_symlinks=False)
        except FileExistsError:
            if path.is_symlink()or path.read_bytes()!=data:raise ValueError('immutable artifact conflict')
    finally:temporary.unlink(missing_ok=True)


def load_prefix(path,manifest,kind,command,managed):
    if not path.exists():return[]
    try:
        text=path.read_bytes().decode();lines=text.split('\n')
        if lines[-1]=='':lines.pop()
        rows=[json.loads(line)for line in lines]
    except(ValueError,UnicodeError):raise ValueError('corrupt receipt prefix')
    if len(rows)>len(manifest[kind]):raise ValueError('receipt overflow')
    for index,row in enumerate(rows):
        if not isinstance(row,dict)or set(row)!={'batch_sha256','index','record'}or type(row['index'])is not int or row['index']!=index or row['batch_sha256']!=digest(manifest):raise ValueError('receipt identity')
        native=command('HGET',managed[5 if kind=='events'else 6],manifest['batch_id']+':'+str(index))
        if native is None or digest(row['record'])!=digest(record(native)):raise ValueError('receipt does not match native ledger')
    return rows


def append(path,row):
    needs_separator=path.exists()and path.stat().st_size>0 and not path.read_bytes().endswith(b'\n')
    with path.open('ab')as stream:
        if needs_separator:stream.write(b'\n')
        stream.write(canonical(row)+b'\n');stream.flush();os.fsync(stream.fileno())


def products(manifest,event_rows,query_rows):
    return {'schema':1,'batch_id':manifest['batch_id'],'batch_sha256':digest(manifest),'events':len(event_rows),'queries':len(query_rows),
            'accepted_new':sum(r['record']['event']['accepted']and not r['record']['reused']for r in event_rows),
            'rejected_new':sum(not r['record']['event']['accepted']and not r['record']['reused']for r in event_rows),
            'replayed':sum(r['record']['reused']for r in event_rows),
            'events_sha256':digest(event_rows),'queries_sha256':digest(query_rows)}


def complete_state(command,managed,manifest):
    state=record(command('HGET',managed[3],manifest['batch_id']))
    if (set(state)!={'digest','events_done','queries_done','phase','epoch'}or
            any(type(state[field])is not int for field in('events_done','queries_done','epoch'))or
            state['digest']!=digest(manifest)or state['phase']!='complete'or
            state['events_done']!=len(manifest['events'])or state['queries_done']!=len(manifest['queries'])or not 0<=state['epoch']<=1000000000):raise ValueError('native batch incomplete')
    for ledger,kind in[(managed[5],'events'),(managed[6],'queries')]:
        present={key for key in command('HKEYS',ledger)if key.startswith(manifest['batch_id']+':')}
        expected={manifest['batch_id']+':'+str(index)for index in range(len(manifest[kind]))}
        if present!=expected:raise ValueError('native cursor rows differ')
    return state


def run_batch(command,prefix,manifest,root,after_native=None,after_receipt=None):
    batch_sha=validate(manifest);managed=native_preflight(command,prefix,manifest)
    directory=directory_for(root,manifest['batch_id'])
    events=load_prefix(directory/'events.jsonl',manifest,'events',command,managed)
    queries=load_prefix(directory/'queries.jsonl',manifest,'queries',command,managed)
    publish(directory/'input.json',manifest)
    command('EVAL',BEGIN,len(managed),*managed,manifest['batch_id'],batch_sha,len(manifest['events']))
    for kind,rows,ledger,script in [('events',events,5,APPLY),('queries',queries,6,SNAPSHOT)]:
        for index in range(len(rows),len(manifest[kind])):
            entry=manifest[kind][index];field=manifest['batch_id']+':'+str(index);raw=command('HGET',managed[ledger],field)
            if raw is None:
                args=[manifest['batch_id'],index,canonical(entry),digest(entry),str(entry['stamp']if kind=='events'else entry['now'])]
                args+=[len(manifest['events']),len(manifest['queries'])]if kind=='events'else[len(manifest['queries'])]
                raw=command('EVAL',script,len(managed),*managed,*args)
                if after_native is not None:after_native(kind,index)
            row={'batch_sha256':batch_sha,'index':index,'record':record(raw)}
            append(directory/(kind+'.jsonl'),row);rows.append(row)
            if after_receipt is not None:after_receipt(kind,index)
    state=complete_state(command,managed,manifest)
    for index,row in enumerate(queries):
        snapshot=row['record'];publish(directory/('candidates-%03d.json'%index),{'query_id':snapshot['query_id'],'epoch':snapshot['epoch'],'candidates':snapshot['candidates']})
        publish(directory/('result-%03d.json'%index),{'query_id':snapshot['query_id'],'epoch':snapshot['epoch'],'partial':False,'items':snapshot['items']})
    result=products(manifest,events,queries);publish(directory/'manifest.json',result)
    return result
